#include <pthread.h>
#include <stdio.h>

int main() {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    int pshared;
    int ret = pthread_mutexattr_getpshared(&attr, &pshared);
    if (ret == 0) {
        printf("Pshared value: %d\n", pshared);
    }
    pthread_mutexattr_destroy(&attr);
    return 0;
}
